import{_ as t,c as o,o as a,ae as s}from"./chunks/framework.Bi6zybwU.js";const d=JSON.parse('{"title":"Table Style Settings","description":"Table Style Settings","frontmatter":{"title":"Table Style Settings","description":"Table Style Settings"},"headers":[],"relativePath":"guide/styling-design/table-style-settings.md","filePath":"guide/styling-design/table-style-settings.md"}'),n={name:"guide/styling-design/table-style-settings.md"};function i(l,e,r,g,h,b){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="table-style-settings" tabindex="-1">Table Style Settings <a class="header-anchor" href="#table-style-settings" aria-label="Permalink to &quot;Table Style Settings&quot;">​</a></h1><p>**Ninja Tables **always brings powerful features, and **Table Style Customization **under the <strong>Table Design</strong> tab is one of them. Using this feature, you can quickly customize and configure your tables differently. Let&#39;s dive into this simple guide to help you get started with the Basic Styling of your table. Go to a table and click on the <strong>Table Design</strong> tab beside the <strong>Table Configurations</strong> tab. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-Ui-table-design-tab-1024x588.webp" alt="New Ui table design tab"> There&#39;s device segment and it consists of three device categories <strong>Desktop, tablet, and mobile</strong>. You can click and see how the table looks on respective devices. You will see a variety of design options that appear to choose from. In this section, you will find three design options for configuring your tables. They are <strong>Styling</strong>, <strong>Table</strong> <strong>Colors</strong> &amp; <strong>Other</strong>.</p><h2 id="tabs-under-table-design" tabindex="-1">Tabs Under Table Design <a class="header-anchor" href="#tabs-under-table-design" aria-label="Permalink to &quot;Tabs Under Table Design&quot;">​</a></h2><p>The Table Design tab shows 3 separate tabs from where you can pick multiple designing and customizing options.</p><ul><li>Styling</li><li>Table Colors</li><li>Other</li></ul><h3 id="styling" tabindex="-1"><strong>Styling</strong> <a class="header-anchor" href="#styling" aria-label="Permalink to &quot;**Styling**&quot;">​</a></h3><p>On the right sidebar, you will notice the first tab, named **Styling. **This tab itself has 3 separate styling options. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-UI-table-design-tabs-1024x649.webp" alt="New UI table design tabs"></p><ul><li>The first one is the** selecting styling library**, which manages the library you have to work with. Three different libraries are available in this segment: <strong>Semantic UI</strong>, <strong>Bootstrap 4</strong> &amp; <strong>Bootstrap 3</strong>. Each of these libraries has various components to toggle on/off - Single line cells, fixed layout, hover rows, striped rows, compact table, etc.</li><li>The second one is the <strong>Features</strong> which offers several functions to toggle on/off - table title**,** table description, hide header row, hide all borders, enable visitors to filter or search the table, and many more. Check these options according to your styling needs.</li><li>Last but not least, with a <strong>stackable table</strong>, you can show your rows as a list item. Once you enable it, you will get options to choose the device you want your table to appear in a stacked form. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-table-ui-stackable-table-703x1024.webp" alt="New table ui stackable table"></li></ul><h3 id="table-colors" tabindex="-1"><strong>Table Colors</strong> <a class="header-anchor" href="#table-colors" aria-label="Permalink to &quot;**Table Colors**&quot;">​</a></h3><p>You can style your table in 13 different <strong>pre-defined color schemes</strong>. You will find many custom color options for your table design in the &quot;<strong>Custom Scheme</strong>&quot; tab. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-Ui-predefined-color-scheme-1024x437.webp" alt="New Ui predefined color scheme"> We&#39;ll explain more about <a href="https://ninjatables.com/docs/table-color-settings/" target="_blank" rel="noreferrer">table colors</a> in the next doc.</p><h3 id="other" tabindex="-1"><strong>Other</strong> <a class="header-anchor" href="#other" aria-label="Permalink to &quot;**Other**&quot;">​</a></h3><p>Under the <strong><a href="https://ninjatables.com/docs/other-design-settings/" target="_blank" rel="noreferrer">Others</a></strong> tab, you will find a few more options to style your table.</p><ul><li><strong>Pagination</strong>: You can select how many items you want to show per page in this section. You can also disable pagination here.</li><li><strong>Pagination Position</strong>: Select where you want the pagination buttons placed- Left, Center, Right, or Default.</li><li><strong>Search Bar Position</strong>: Decide the position of the search bar- Left, Center, Right, or Default.</li><li><strong>Select Sorting Method</strong>: Sort the table rows manually or by created at or by column.</li><li><strong>Row Details (Responaive drawer)</strong>: Default, Expand First, or Expand All.</li><li><strong>Toggle Position</strong>: First column and Last Column.</li><li><strong>Extra CSS Class for the table</strong>: Add an extra CSS class.</li><li><strong>Enable Sticky Header</strong>: Make a table header sticky.</li><li><strong>Table Font Settings</strong>: Select font family and font size for the table data.</li></ul>',13)])])}const u=t(n,[["render",i]]);export{d as __pageData,u as default};
